const defaults={collections:['Personal','Work','Experiments'],overrides:{},custom:[],order:[],favorites:[],hidden:[],name:'dock',opened:{},sort:'custom',density:'comfortable',width:'standard',descriptions:true,accent:'neutral',tone:'pure',font:'system',corners:'balanced',theme:'system'};
