function toast(t,undo){$('#toast').textContent=t;if(undo){const b=document.createElement('button');b.textContent='Undo';b.onclick=()=>{undo();$('#toast').classList.remove('show')};$('#toast').append(b)}$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),undo?7000:2800)}
function apply(){if(!state.opened||typeof state.opened!=='object'||Array.isArray(state.opened))state.opened={};if(!['custom','name','recent'].includes(state.sort))state.sort='custom';if(!['comfortable','compact'].includes(state.density))state.density='comfortable';if(!['standard','wide'].includes(state.width))state.width='standard';document.body.classList.toggle('compact',state.density==='compact');document.body.classList.toggle('wide',state.width==='wide');document.body.classList.toggle('hide-descriptions',state.descriptions===false);Object.assign(state,DockAppearance.normalize(state));DockAppearance.apply(state);const dark=DockAppearance.isDark();$('#brandname').textContent=state.name;document.title=state.name+' — Projects';$('#theme-toggle').innerHTML=dark?icons.sun:icons.moon;$('#theme-toggle').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`)}
