function clearFilters(){scope='All projects';query='';$('#search').value='';render()}
$('#clear-filters').onclick=clearFilters;$('#collections-shortcut').onclick=collectionModal;$('#sort-projects').onchange=e=>{state.sort=e.target.value;save()};$$('[data-view]').forEach(b=>b.onclick=()=>{scope=b.dataset.view;render()});
$('#settings').onclick=settings;$('#theme-toggle').onclick=()=>{state.theme=DockAppearance.isDark()?'light':'dark';save()};$('#new-project').onclick=()=>projectModal();$('#search').oninput=e=>{query=e.target.value;render()};$('#collection-filter').onchange=e=>{scope=e.target.value;render()};document.addEventListener('keydown',e=>{if(e.isComposing||$('#modal').open)return;const target=document.activeElement,typing=['INPUT','TEXTAREA','SELECT'].includes(target.tagName)||target.isContentEditable;const shortcut=(e.metaKey||e.ctrlKey)&&!e.altKey&&e.key.toLowerCase()==='k';if(shortcut||e.key==='/'&&!typing&&!e.ctrlKey&&!e.metaKey&&!e.altKey){e.preventDefault();$('#search').focus();if(shortcut)$('#search').select()}if(e.key==='Escape'&&target===$('#search')&&query){e.preventDefault();query='';$('#search').value='';render()}});$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dismissModal()}};
async function refresh(){try{const response=await fetch('projects.json?t='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error();const data=await response.json();if(JSON.stringify(data)!==JSON.stringify(discovered)){discovered=data;for(const p of data)if(p.collection&&!state.collections.includes(p.collection))state.collections.push(p.collection);render()}$('#discovery-label').textContent=''}catch{$('#discovery-label').textContent='Could not refresh projects. Retrying…'}}apply();render();refresh();setInterval(refresh,15000);

// Identity is supplied by the server only after authentication and bot verification.
fetch('/_security/identity',{cache:'no-store'}).then(async r=>{if(!r.ok)return;const identity=await r.json();if(typeof identity.email!=='string')return;$('#account').hidden=false;$('#account').title='Sign out of '+identity.email;}).catch(()=>{});

document.addEventListener('dock-appearance',()=>{if(typeof state!=='undefined'){const dark=DockAppearance.isDark();$('#theme-toggle').innerHTML=dark?icons.sun:icons.moon;$('#theme-toggle').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`)}});

window.addEventListener('storage',e=>{if((e.key==='dock-v1'||e.key===null)&&!$('#modal').open){const next=unpackState(DockAppearance.read());state={...structuredClone(defaults),...next};apply();render()}});

$('#modal').addEventListener('cancel',()=>{onModalDismiss();onModalDismiss=()=>{}});
